--
-- Estructura para la vista `inventory_movements_view`
--
DROP TABLE IF EXISTS `inventory_movements_view`;

DROP VIEW IF EXISTS `inventory_movements_view`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `inventory_movements_view`  AS SELECT concat('IN_',`de`.`id`,'_',`sl`.`id`) AS `movement_id`, 'IN' AS `movement_type`, `sl`.`tenant_id` AS `tenant_id`, `sl`.`company_id` AS `company_id`, `de`.`stock_item_id` AS `stock_item_id`, `de`.`material_id` AS `material_id`, `sl`.`warehouse_id` AS `warehouse_id`, `sl`.`location_id` AS `location_id`, `sl`.`id` AS `stock_lot_id`, `sl`.`lot_code` AS `lot_code`, `sl`.`expiration_date` AS `expiration_date`, `e`.`date_entry` AS `movement_date`, `de`.`entered_quantity` AS `quantity`, (case when (upper(coalesce(`sv`.`value_text`,`sd`.`default_value`,'PEN')) = 'USD') then (case upper(`e`.`currency_invoice`) when 'USD' then (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) when 'PEN' then (case when ((`e`.`currency_venta` is not null) and (`e`.`currency_venta` > 0)) then ((case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) / `e`.`currency_venta`) else (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) end) else (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) end) when (upper(coalesce(`sv`.`value_text`,`sd`.`default_value`,'PEN')) = 'PEN') then (case upper(`e`.`currency_invoice`) when 'PEN' then (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) when 'USD' then (case when ((`e`.`currency_compra` is not null) and (`e`.`currency_compra` > 0)) then ((case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) * `e`.`currency_compra`) else (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) end) else (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) end) else (case when ((`de`.`total_detail` is not null) and (`de`.`entered_quantity` > 0)) then (`de`.`total_detail` / `de`.`entered_quantity`) else `de`.`unit_price` end) end) AS `unit_cost`, 'entry' AS `source_type`, `e`.`id` AS `source_id` FROM ((((`detail_entries` `de` join `entries` `e` on((`e`.`id` = `de`.`entry_id`))) join `stock_lots` `sl` on((`sl`.`detail_entry_id` = `de`.`id`))) left join `setting_definitions` `sd` on(((`sd`.`key` = 'finance.base_currency') and (`sd`.`scope` = 'company') and (`sd`.`is_active` = 1)))) left join `setting_values` `sv` on(((`sv`.`setting_definition_id` = `sd`.`id`) and (`sv`.`tenant_id` = `sl`.`tenant_id`) and (`sv`.`company_id` = `sl`.`company_id`) and (`sv`.`branch_id` is null)))) WHERE ((`e`.`deleted_at` is null) AND (`de`.`stock_item_id` is not null)) union all select concat('OUT_',`od`.`id`) AS `movement_id`,'OUT' AS `movement_type`,`sl`.`tenant_id` AS `tenant_id`,`sl`.`company_id` AS `company_id`,`od`.`stock_item_id` AS `stock_item_id`,`od`.`material_id` AS `material_id`,`od`.`warehouse_id` AS `warehouse_id`,`od`.`location_id` AS `location_id`,`od`.`stock_lot_id` AS `stock_lot_id`,`sl`.`lot_code` AS `lot_code`,`sl`.`expiration_date` AS `expiration_date`,`o`.`request_date` AS `movement_date`,`od`.`percentage` AS `quantity`,`od`.`unit_cost` AS `unit_cost`,'output' AS `source_type`,`o`.`id` AS `source_id` from ((`output_details` `od` join `outputs` `o` on((`o`.`id` = `od`.`output_id`))) left join `stock_lots` `sl` on((`sl`.`id` = `od`.`stock_lot_id`))) where ((`o`.`state` in ('attended','confirmed')) and (`od`.`stock_item_id` is not null))  ;

